(6798683, 1021933, 114285, '<td valign="top">Fantastic POV, Love everything about it.</td>', 'Fantastic POV, Love everything about it.', '2012-06-20 10:12:51.000000', NULL, 1),
(6798684, 1021019, 3936, '<td valign="top">Looks like Ben...  Which is not a bad thing.  If you are not Ben, you may be getting some bling from him, and/or Don.</td>', 'Looks like Ben...  Which is not a bad thing.  If you are not Ben, you may be getting some bling from him, and/or Don.', '2012-06-20 10:14:06.000000', NULL, 1),
