(6798700, 1021734, 114285, '<td valign="top">Gorgeous tones, and sunlight.</td>', 'Gorgeous tones, and sunlight.', '2012-06-20 10:25:17.000000', NULL, 1),
(6798719, 1021931, 142473, '<td valign="top">This image immediately jumped out to me.  Incredible dimension and mastery of composition shown here.  Well done.</td>', 'This image immediately jumped out to me.  Incredible dimension and mastery of composition shown here.  Well done.', '2012-06-20 11:05:22.000000', NULL, 1),
(6798721, 1021834, 142473, '<td valign="top">Great colors and abstractia.  This would have probably done very well in the nature abstract challenge coming up too.  Quite enjoyable.  This is one of those shots that would be great blown up on a wall.</td>', 'Great colors and abstractia.  This would have probably done very well in the nature abstract challenge coming up too.  Quite enjoyable.  This is one of those shots that would be great blown up on a wall.', '2012-06-20 11:07:11.000000', NULL, 1),
(6798731, 1022003, 65234, '<td valign="top">Oh, dear :-(  Wildfires are SO destructive, at least in the short term.  Interesting contrast with the growing fields, though it occurs to me that the contrast would be even more dramatic if the fields were greener.  Never mind if they weren''t in reality ;-)</td>', 'Oh, dear :-(  Wildfires are SO destructive, at least in the short term.  Interesting contrast with the growing fields, though it occurs to me that the contrast would be even more dramatic if the fields were greener.  Never mind if they weren''t in reality ;-)', '2012-06-20 11:55:04.000000', NULL, 1),
(6798733, 1021019, 65234, '<td valign="top">This reminds me of childhood visits to my grandparents, where there was always a fine black dust all over everything outside from the nearby factories.</td>', 'This reminds me of childhood visits to my grandparents, where there was always a fine black dust all over everything outside from the nearby factories.', '2012-06-20 11:58:42.000000', NULL, 1),
(6798734, 1021973, 65234, '<td valign="top">Like the old-timey tone to this.</td>', 'Like the old-timey tone to this.', '2012-06-20 11:59:15.000000', NULL, 1),
(6798735, 1021375, 65234, '<td valign="top">Creative concept!  And gorgeous cat, so I have to give you a bonus point for that, even if the cat looks more like s/he''s questioning why you''re blowing bubbles instead of stalking them :-)</td>', 'Creative concept!  And gorgeous cat, so I have to give you a bonus point for that, even if the cat looks more like s/he''s questioning why you''re blowing bubbles instead of stalking them :-)', '2012-06-20 12:01:18.000000', NULL, 1),
(6798736, 1021969, 65234, '<td valign="top">This one makes me smile.</td>', 'This one makes me smile.', '2012-06-20 12:01:42.000000', NULL, 1),
(6798737, 1021978, 65234, '<td valign="top">Lovely weeds.  Really like the colors and dreamy feel to this.</td>', 'Lovely weeds.  Really like the colors and dreamy feel to this.', '2012-06-20 12:02:12.000000', NULL, 1),
(6798738, 1021688, 65234, '<td valign="top">Perfectly framed!</td>', 'Perfectly framed!', '2012-06-20 12:02:33.000000', NULL, 1),
(6798739, 1021417, 65234, '<td valign="top">Adorable!  And nicely set off by the flowers both in and out of focus.  I see at least one bonus bug, too ;-)</td>', 'Adorable!  And nicely set off by the flowers both in and out of focus.  I see at least one bonus bug, too ;-)', '2012-06-20 12:03:43.000000', NULL, 1),
