(6798743, 1021921, 65234, '<td valign="top">Kinda'' spooky!</td>', 'Kinda'' spooky!', '2012-06-20 12:06:32.000000', NULL, 1),
(6798744, 1021418, 65234, '<td valign="top">Nature is cruel.  This tells a story well.  But ... it looks to me like the plant is farther from the camera than the fly, which makes me think it''s background bokeh.  For this challenge I suspect it might have been better if the fly was OOF and the plant was in focus.  JMO.</td>', 'Nature is cruel.  This tells a story well.  But ... it looks to me like the plant is farther from the camera than the fly, which makes me think it''s background bokeh.  For this challenge I suspect it might have been better if the fly was OOF and the plant was in focus.  JMO.', '2012-06-20 12:09:49.000000', NULL, 1),
(6798745, 1021997, 65234, '<td valign="top">Not often they pause and pose like this.</td>', 'Not often they pause and pose like this.', '2012-06-20 12:10:12.000000', NULL, 1),
(6798746, 1021848, 65234, '<td valign="top">Nicely glistening.</td>', 'Nicely glistening.', '2012-06-20 12:11:03.000000', NULL, 1),
