(6798818, 1021606, 66384, '<td valign="top">Beautiful color and contrast, and the perfect amount of foreground blur to guide me to the subject.</td>', 'Beautiful color and contrast, and the perfect amount of foreground blur to guide me to the subject.', '2012-06-20 14:06:06.000000', NULL, 1),
(6798822, 1021688, 66384, '<td valign="top">I see that you have blurred the fence in the foreground. This is not what I think of as bokeh, but the image is very nice, and I''ll keep an open mind about the bokeh.</td>', 'I see that you have blurred the fence in the foreground. This is not what I think of as bokeh, but the image is very nice, and I''ll keep an open mind about the bokeh.', '2012-06-20 14:08:49.000000', NULL, 1),
(6798824, 1021921, 66384, '<td valign="top">Eeeerie!</td>', 'Eeeerie!', '2012-06-20 14:10:10.000000', NULL, 1),
(6798830, 1021939, 66384, '<td valign="top">The web is beautiful. I wish the spider was easier to see. It gets very busy there in the middle. Still, I love your bokeh.</td>', 'The web is beautiful. I wish the spider was easier to see. It gets very busy there in the middle. Still, I love your bokeh.', '2012-06-20 14:16:40.000000', NULL, 1),
