(6798835, 1021088, 66384, '<td valign="top">Excellent composition, clarity of subject, and beautiful bokeh!</td>', 'Excellent composition, clarity of subject, and beautiful bokeh!', '2012-06-20 14:22:11.000000', NULL, 1),
(6798846, 1021644, 106550, '<td valign="top">Truly gives the feeling of rejection. Love the composition and the story. Great job!</td>', 'Truly gives the feeling of rejection. Love the composition and the story. Great job!', '2012-06-20 14:56:08.000000', NULL, 1),
