(6799524, 1021939, 149507, '<td valign="top">Your bokeh has an extraordinary variety of colors to it.</td>', 'Your bokeh has an extraordinary variety of colors to it.', '2012-06-21 23:05:08.000000', NULL, 1),
(6799526, 1021799, 149507, '<td valign="top">This has a beautiful combination of colors and textures.</td>', 'This has a beautiful combination of colors and textures.', '2012-06-21 23:06:34.000000', NULL, 1),
(6799527, 1021938, 149507, '<td valign="top">I love the clarity of the focal point</td>', 'I love the clarity of the focal point', '2012-06-21 23:07:58.000000', NULL, 1),
(6799530, 1021941, 149507, '<td valign="top">A great idea for making the foreground bokeh part of the concept.</td>', 'A great idea for making the foreground bokeh part of the concept.', '2012-06-21 23:09:50.000000', NULL, 1),
(6799539, 1021921, 149507, '<td valign="top">The foreground bokeh is confusing. There''s no easy explanation for why it''s there and it''s different in tone from the rest of the photo.</td>', 'The foreground bokeh is confusing. There''s no easy explanation for why it''s there and it''s different in tone from the rest of the photo.', '2012-06-21 23:13:55.000000', NULL, 1),
(6799541, 1021931, 149507, '<td valign="top">The woman in the foreground ends up being a very large blurry area in front of an in-focus photo. It might have worked better if there was more of a transition from in-focus to blurry.</td>', 'The woman in the foreground ends up being a very large blurry area in front of an in-focus photo. It might have worked better if there was more of a transition from in-focus to blurry.', '2012-06-21 23:15:58.000000', NULL, 1),
(6799543, 1021996, 149507, '<td valign="top">The flower seems too shaded and should be brightened up some.</td>', 'The flower seems too shaded and should be brightened up some.', '2012-06-21 23:16:40.000000', NULL, 1),
(6799549, 1021948, 149507, '<td valign="top">The foreground looked to me like it was in the background at first, then my eyes had to adjust.</td>', 'The foreground looked to me like it was in the background at first, then my eyes had to adjust.', '2012-06-21 23:19:11.000000', NULL, 1),
(6799550, 1021811, 149507, '<td valign="top">This would look better without the bright overcast sky.</td>', 'This would look better without the bright overcast sky.', '2012-06-21 23:20:13.000000', NULL, 1),
(6799552, 1022011, 149507, '<td valign="top">Probably needs more contrast</td>', 'Probably needs more contrast', '2012-06-21 23:21:05.000000', NULL, 1),
(6799553, 1021512, 149507, '<td valign="top">I feel like the foreground foliage ends up being a haze that obscures the bridge too much.</td>', 'I feel like the foreground foliage ends up being a haze that obscures the bridge too much.', '2012-06-21 23:22:21.000000', NULL, 1),
(6799557, 1021893, 149507, '<td valign="top">It seems like the figurine is of the Eiffel Tower, but it should be slightly clearer so it''s easier to tell. Including the real thing in the background might have been interesting, too.</td>', 'It seems like the figurine is of the Eiffel Tower, but it should be slightly clearer so it''s easier to tell. Including the real thing in the background might have been interesting, too.', '2012-06-21 23:24:38.000000', NULL, 1),
(6799560, 1021343, 149507, '<td valign="top">Blown-out sky. Needs less exposure, less highlights and more contrast. The eyes could be selectively brightened as well since this is Advanced Editing.</td>', 'Blown-out sky. Needs less exposure, less highlights and more contrast. The eyes could be selectively brightened as well since this is Advanced Editing.', '2012-06-21 23:26:23.000000', NULL, 1),
(6799562, 1021716, 149507, '<td valign="top">Needs more contrast.</td>', 'Needs more contrast.', '2012-06-21 23:27:27.000000', NULL, 1),
