(6799572, 1021234, 149507, '<td valign="top">The people are a bit overwhelmed by the bright sky behind them.</td>', 'The people are a bit overwhelmed by the bright sky behind them.', '2012-06-21 23:34:14.000000', NULL, 1),
(6799573, 1021960, 149507, '<td valign="top">The focal point could be a bit sharper.</td>', 'The focal point could be a bit sharper.', '2012-06-21 23:35:12.000000', NULL, 1),
(6799577, 1022014, 149507, '<td valign="top">The single M&amp;M looks flat and could use more depth. Also, you can see whatever it''s propped up by and that''s distracting.</td>', 'The single M&M looks flat and could use more depth. Also, you can see whatever it''s propped up by and that''s distracting.', '2012-06-21 23:37:23.000000', NULL, 1),
(6799578, 1021866, 149507, '<td valign="top">Parts of the leaves are over-exposed.</td>', 'Parts of the leaves are over-exposed.', '2012-06-21 23:38:30.000000', NULL, 1),
(6799579, 1021369, 149507, '<td valign="top">The bridge is dark and is overwhelmed some by the brightness of the leaves in the foreground.</td>', 'The bridge is dark and is overwhelmed some by the brightness of the leaves in the foreground.', '2012-06-21 23:39:13.000000', NULL, 1),
(6799582, 1021283, 149507, '<td valign="top">It''s a nice exposure of the bridge, trees and their reflections. However, the foreground bokeh is insignificant and the lower half of the photo ends up being featureless.</td>', 'It''s a nice exposure of the bridge, trees and their reflections. However, the foreground bokeh is insignificant and the lower half of the photo ends up being featureless.', '2012-06-21 23:42:09.000000', NULL, 1),
(6799583, 1021992, 149507, '<td valign="top">The leaves in the foreground are too bright and detract too much from the subject.</td>', 'The leaves in the foreground are too bright and detract too much from the subject.', '2012-06-21 23:43:00.000000', NULL, 1),
(6799585, 1021296, 149507, '<td valign="top">The stem is placed in the foreground to provide bokeh according to the theme, but I feel it just ends up obscuring the subject and the photo would be better without it (but wouldn''t meet the challenge).</td>', 'The stem is placed in the foreground to provide bokeh according to the theme, but I feel it just ends up obscuring the subject and the photo would be better without it (but wouldn''t meet the challenge).', '2012-06-21 23:45:19.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6799588, 1021420, 149507, '<td valign="top">There''s not enough of the daisies to offset all the green grass. They''d look better photographed face-on instead of edge-on.</td>', 'There''s not enough of the daisies to offset all the green grass. They''d look better photographed face-on instead of edge-on.', '2012-06-21 23:47:19.000000', NULL, 1),
(6799589, 1021837, 149507, '<td valign="top">Good job capturing foreground bokeh that contributes to the composition.</td>', 'Good job capturing foreground bokeh that contributes to the composition.', '2012-06-21 23:48:36.000000', NULL, 1),
(6799591, 1021817, 149507, '<td valign="top">The rose is lacking in detail. It looks flat and featureless.</td>', 'The rose is lacking in detail. It looks flat and featureless.', '2012-06-21 23:49:09.000000', NULL, 1),
(6799592, 1021917, 64446, '<td valign="top">Lovely image, but it seems you''ve got more of a background bokeh, not foreground...</td>', 'Lovely image, but it seems you''ve got more of a background bokeh, not foreground...', '2012-06-21 23:49:53.000000', NULL, 1),
(6799593, 1022006, 149507, '<td valign="top">The foreground is so blurry it makes the photo just seem washed out.</td>', 'The foreground is so blurry it makes the photo just seem washed out.', '2012-06-21 23:50:07.000000', NULL, 1),
(6799594, 1021848, 149507, '<td valign="top">This is a lovely composition. The yellow areas seem too bright and lacking in detail.</td>', 'This is a lovely composition. The yellow areas seem too bright and lacking in detail.', '2012-06-21 23:50:55.000000', NULL, 1),
(6799598, 1021989, 149507, '<td valign="top">The bee could be better lit. It feels lost in the shadows.</td>', 'The bee could be better lit. It feels lost in the shadows.', '2012-06-21 23:53:44.000000', NULL, 1),
(6799659, 1022004, 142273, '<td valign="top">Among top 3 for me! Great capture!</td>', 'Among top 3 for me! Great capture!', '2012-06-22 00:45:33.000000', NULL, 1),
