(6800195, 1022016, 149507, '<td valign="top">I really like the concept of the foreground bokeh being bubbles that are blown by the boy. Since half of his mouth is cropped out it''s not completely clear that that was what you were trying to convey. I would prefer just a little bit more of his face (especially the mouth) be included.</td>', 'I really like the concept of the foreground bokeh being bubbles that are blown by the boy. Since half of his mouth is cropped out it''s not completely clear that that was what you were trying to convey. I would prefer just a little bit more of his face (especially the mouth) be included.', '2012-06-22 12:52:53.000000', NULL, 1),
(6800299, 1022016, 138253, '<td valign="top">haha, i love the expression<br/>great bokeh</td>', 'haha, i love the expressiongreat bokeh', '2012-06-22 14:42:32.000000', NULL, 1),
(6800301, 1021893, 138253, '<td valign="top">my favorite of the challenge. love the detail of the city.</td>', 'my favorite of the challenge. love the detail of the city.', '2012-06-22 14:45:50.000000', NULL, 1),
