(6800540, 1021982, 124815, '<td valign="top">Heart breaking and beautiful</td>', 'Heart breaking and beautiful', '2012-06-22 22:01:23.000000', NULL, 1),
(6800604, 1021906, 113412, '<td valign="top">Delicious pure, clean colors. I''m right there, looking through the wildflowers at the bird.</td>', 'Delicious pure, clean colors. I''m right there, looking through the wildflowers at the bird.', '2012-06-22 23:33:28.000000', NULL, 1),
(6800605, 1021417, 113412, '<td valign="top">Lovely bokeh, with a sharp, adorable subject.</td>', 'Lovely bokeh, with a sharp, adorable subject.', '2012-06-22 23:34:42.000000', NULL, 1),
(6800607, 1021045, 113412, '<td valign="top">Wow! What a shallow depth of field! Perfect sharpness amid lovely bokeh.</td>', 'Wow! What a shallow depth of field! Perfect sharpness amid lovely bokeh.', '2012-06-22 23:35:37.000000', NULL, 1),
