(6800724, 1022016, 129694, '<td valign="top">Awesome!</td>', 'Awesome!', '2012-06-23 08:59:57.000000', NULL, 1),
(6800732, 1021730, 114285, '<td valign="top">Lovely shot, but one nitpick, I would of cropped the top right white corner it spoils this!</td>', 'Lovely shot, but one nitpick, I would of cropped the top right white corner it spoils this!', '2012-06-23 09:50:26.000000', NULL, 1),
